<script>(function(){var url=@json(route('admin.updates.status')),seen=@json(($state['status']??'')==='running'),reload=false;function sb(b,a,r){if(!b)return;var i=b.querySelector('i'),t=document.getElementById('nodexa-update-button-text');b.disabled=r||!a;if(i)i.className=r?'fa fa-spinner fa-spin':(a?'fa fa-cloud-download':'fa fa-check');if(t)t.textContent=r?'Installerer…':(a?'Opdater nu':'Opdateret')}function prog(s){var n=Math.max(0,Math.min(100,parseInt(s.progress||0))),bar=document.getElementById('nxProgressBar'),pc=document.getElementById('nxProgressPercent'),step=document.getElementById('nxProgressStep');bar.style.width=n+'%';pc.textContent=n+'%';step.textContent=s.step||'Arbejder…'}function poll(){fetch(url,{headers:{Accept:'application/json'},credentials:'same-origin'}).then(r=>r.json()).then(d=>{var s=d.state||{},a=d.update_available===true,b=document.getElementById('nodexa-update-button'),title=document.getElementById('nxTitle'),msg=document.getElementById('nxMessage'),st=document.getElementById('nxStatusText'),p=document.getElementById('nxProgress'),ic=document.querySelector('#nxUpdateIcon i');prog(s);if(s.status==='running'){seen=true;title.textContent='Installerer opdatering…';msg.textContent=s.message||'Opdateringen installeres automatisk.';st.textContent='Opdaterer nu';p.classList.add('show');ic.className='fa fa-refresh fa-spin';sb(b,a,true);return}if(s.status==='failed'&&seen){p.classList.add('show');title.textContent='Opdateringen fejlede';msg.textContent=s.message||'Opdateringen kunne ikke gennemføres.';st.textContent='Opdatering fejlede';ic.className='fa fa-times';sb(b,a,false);return}if(s.status==='success'&&seen){p.classList.add('show');title.textContent='Nodexa er opdateret';msg.textContent='Den nye version er installeret.';st.textContent='Systemet er opdateret';ic.className='fa fa-check';sb(b,false,false);if(!reload){reload=true;setTimeout(()=>location.reload(),2200)}return}p.classList.remove('show');title.textContent=a?'Ny Nodexa-opdatering':'Nodexa er opdateret';msg.textContent=a?'En nyere version er klar til installation.':'Du bruger allerede den nyeste version.';st.textContent=a?'Opdatering tilgængelig':'Systemet er opdateret';ic.className=a?'fa fa-cloud-download':'fa fa-check';sb(b,a,false)}).catch(()=>{})}setInterval(poll,1500);poll()})();</script>
